import { Component, OnInit, Input, ViewChild } from '@angular/core';
import { BrTableAction, BrTableColumn, DataExport, DefaultsService, delay, GovBrTableModule, GovBrInputModule, TableComponent } from '@serpro/ngx-dsgovbr';
import { ColumnMode } from '@siemens/ngx-datatable';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, FormsModule, ReactiveFormsModule, Validators } from '@angular/forms';
import { DadosAbertosService } from '../../../services/dados-abertos.service';
import { DispositivoService } from '../../../services/dispositivo.service';
import { Subscription } from 'rxjs';
import { TooltipDirective } from "ngx-bootstrap/tooltip";
import { MensagemService } from '../../../services/mensagem.service';

@Component({
  selector: 'consultar-fundamentacoes-todas',
  templateUrl: './consultar-fundamentacoes-todas.component.html',
  styleUrl: './consultar-fundamentacoes-todas.component.scss',
  standalone: true,
  imports: [
    CommonModule,
    ReactiveFormsModule,
    GovBrTableModule,
    GovBrInputModule,
    TooltipDirective
  ],
})
export class ConsultarFundamentacoesTodasComponent implements OnInit {

  @Input() dataConsulta: Date | null = null;

  @ViewChild('brTable') brTable!: TableComponent;

  private subscriptions: Subscription = new Subscription();
  dispositivo: string = '';

  filtroCodigo: string = '';
  filtroDescricao: string = '';

  // @ViewChild('cellTemplate', { static: true })
  // private cellTemplate!: TemplateRef<any>;

  pageSize = 5;
  currentPage = 1;

  ColumnMode = ColumnMode;

  export!: DataExport;

  tableActions: BrTableAction[] = [];
  tableColumns: BrTableColumn[] = [];

  dadosOriginais: any[] = [];
  dadosFiltrados: any[] = [];

  form!: FormGroup;

  ACAO_CUSTOMIZADA: BrTableAction = {
    //active: true, => isso deixa o botão pressionado por padrão
    actionType: 'customAction',
    actionDescription: 'Ação Personalizada',
    icon: 'fas fa-bell',
    callbackFn: () => {
      alert('Ação personalizada foi acionada!');
    }
  };

  modoFlex: ColumnMode = ColumnMode.flex;
  modoStandard: ColumnMode = ColumnMode.standard;
  modoForce: ColumnMode = ColumnMode.force;

  counter: number = 0;

  colunasDesktop: BrTableColumn[] = [
      {
        name: 'cClassTrib',
        prop: 'codigoClassificacaoTributaria',
        cellClass: 'cell-class',
        headerClass: 'header-class',
        //cellTemplate: this.cellTemplate,
        flexGrow: 1.5
      },
      {
        name: 'Descrição cClassTrib',
        prop: 'descricaoClassificacaoTributaria',
        cellClass: 'cell-class',
        headerClass: 'header-class',
        //cellTemplate: this.cellTemplate,
        flexGrow: 3
      },
      {
        name: 'CST',
        prop: 'codigoSituacaoTributaria',
        cellClass: 'cell-class',
        headerClass: 'header-class',
        //cellTemplate: this.cellTemplate,
        flexGrow: 2
      },
      {
        name: 'Descrição CST',
        prop: 'descricaoSituacaoTributaria',
        cellClass: 'cell-class',
        headerClass: 'header-class',
        //cellTemplate: this.cellTemplate,
        flexGrow: 2
      },
      {
        name: 'Texto Curto',
        prop: 'textoCurto',
        cellClass: 'cell-class',
        headerClass: 'header-class',
        //cellTemplate: this.cellTemplate,
        flexGrow: 2.5
      },
    ];

  colunasXSmall: BrTableColumn[] = [
      {
        name: 'cClassTrib',
        prop: 'codigoClassificacaoTributaria',
        cellClass: 'cell-class',
        headerClass: 'header-class',
        //cellTemplate: this.cellTemplate,
        flexGrow: 1
      },
      {
        name: 'Texto Curto',
        prop: 'textoCurto',
        cellClass: 'cell-class',
        headerClass: 'header-class',
        //cellTemplate: this.cellTemplate,
        flexGrow: 1.5
      },
    ];


  mapExport = (x: any) => [x.codigoClassificacaoTributaria, x.descricaoClassificacaoTributaria, x.codigoSituacaoTributaria, x.descricaoSituacaoTributaria, x.textoCurto];
  EXPORT_COLUMNS = ['Código', 'Descrição', 'CST', 'Descrição CST', 'Texto Curto'];

  dataExportFn = () => {
    return new Promise((resolve) =>
      delay(2000).then(() => resolve(this.dadosOriginais.map(this.mapExport)))
    );
  };

  formatarTexto(texto: string): string {
    if (!texto) {
      return '';
    }
    // substituir \n por quebras de linha reais
    return texto.replace(/\\n/g, '\n');
  }

  baixarDadosJSON() {
    if (!this.dadosOriginais || this.dadosOriginais.length === 0) {
      alert('Não há dados para exportar!');
      return;
    }

    try {
      // Converte os dados para JSON formatado (indentação de 2 espaços)

      const jsonFormatado = JSON.stringify(this.dadosOriginais, null, 2);

      // Cria um blob com o conteúdo JSON
      
      const blob = new Blob([jsonFormatado], { type: 'application/json' });

      // Cria um link temporário para download
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;

      // Define o nome do arquivo com data/hora no formato brasileiro
      const agora = new Date();

      const dataBR = agora.toLocaleString('pt-BR', {
        timeZone: 'America/Sao_Paulo',
        year: 'numeric',
        month: '2-digit',
        day: '2-digit'
      }).replace(/\//g, '-');

      const horaBR = agora.toLocaleString('pt-BR', {
        timeZone: 'America/Sao_Paulo',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
      }).replace(/:/g, '-');

      link.download = `fundamentacoes-legais-${dataBR}_${horaBR}.json`;

      // Executa o download

      document.body.appendChild(link);
      link.click();

      // Remove o link e libera a memória

      document.body.removeChild(link);
      window.URL.revokeObjectURL(url);
    } catch (error) {
      console.error('Erro ao exportar dados:', error);
    }
  }

  constructor(
    private dadosAbertosService: DadosAbertosService,
    private dispositivoService: DispositivoService,
    private formBuilder: FormBuilder,
    private mensagemService: MensagemService,
  ) { }

  ngOnInit(): void {
    this.form = this.formBuilder.group({
      codigoControl: [null, []],
      descricaoControl: [null, []],
    });
    this.export = new DataExport(this.EXPORT_COLUMNS, this.dataExportFn);
    this.export.enabledTypes = ['csv', 'pdf', 'txt', 'xls', 'xml'];
    this.export.config = { csvColumnSeparator: '|' }
    //this.tableActions = [this.ACAO_CUSTOMIZADA];
    this.tableColumns = [...this.colunasDesktop];
    this.setSubscriptions();
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
    this.mensagemService.limpar();
  }

  setSubscriptions() {
    this.subscriptions.add(
      this.dispositivoService.dispositivo$.subscribe((dispositivo: any) => {
        this.dispositivo = dispositivo;
        if (this.dispositivo === 'device-xsmall') {
          this.tableColumns = [...this.colunasXSmall];
        } else {
          this.tableColumns = [...this.colunasDesktop];
        }
      }));
  }

  autoExpanded = false;
  toggleExpandAll() {
    this.autoExpanded = !this.autoExpanded;
  }

  onRowExpanded(event: any) {
  }

  rowExpandableFn = (x: any) => {
    return x == x;
  }

  consultar(data: Date | null) {
    if (data) {
      this.dadosAbertosService.obterFundamentacoesLegais(data).subscribe({
        next: (data) => {
          this.dadosOriginais = data;
          this.dadosFiltrados = data;
          this.mensagemService.mostrar('Sucesso', 'Sucesso', 'Consulta realizada com sucesso.');
        },
        error: (error) => {
          this.mensagemService.mostrar('Erro', 'Erro', 'Erro ao realizar a consulta: ' + error?.message);
        }
      });
    }
  }

  aplicarFiltro() {
    const codigoFiltro = this.form.get('codigoControl')?.value?.toLowerCase() || '';
    const descricaoFiltro = this.form.get('descricaoControl')?.value?.toLowerCase() || '';
    this.dadosFiltrados = this.dadosOriginais.filter(item => {
      const codigoMatch = item.codigoClassificacaoTributaria.toLowerCase().includes(codigoFiltro);
      const descricaoMatch = item.descricaoClassificacaoTributaria.toLowerCase().includes(descricaoFiltro);
      return codigoMatch && descricaoMatch;
    });
  }

  limparFiltro() {
    this.filtroCodigo = '';
    this.filtroDescricao = '';
    this.form.reset();
    this.dadosFiltrados = this.dadosOriginais;
  }

  fecharFiltro() {
    this.brTable.hideFilterRow();
  }

}
